package vn.gastroai.be.domain.admin;
import jakarta.persistence.*; import lombok.*; import java.time.Instant;
@Entity @Table(name="admin_accounts") @Getter @Setter @NoArgsConstructor @AllArgsConstructor
public class AdminAccount { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String email; @Column(name="password_hash",nullable=false) private String passwordHash; @Column(name="full_name") private String fullName; @Column(nullable=false) private boolean active; @Column(name="failed_login_attempts",nullable=false) private int failedLoginAttempts; @Column(name="locked_until") private Instant lockedUntil; @Column(name="password_reset_token_hash") private String passwordResetTokenHash; @Column(name="password_reset_token_expires_at") private Instant passwordResetTokenExpiresAt; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; }
